command:
$ErrorActionPreference = "Stop"
git fetch origin main work/search-v2 --no-tags
if ($LASTEXITCODE -ne 0) { throw "fetch failed" }
if ((git status --short).Count -ne 0) { throw "dirty checkout" }
if ((git rev-parse origin/main).Trim() -ne "ecca3e98000dad764f846be0d6483775b2610fe0") { throw "main moved" }
git checkout work/search-v2
if ($LASTEXITCODE -ne 0) { throw "checkout failed" }
git merge --ff-only origin/work/search-v2
if ($LASTEXITCODE -ne 0) { throw "branch update failed" }

if (-not (Test-Path "out\winui\Release\flyExplorer.exe")) { throw "existing Release binary missing" }

Write-Host "VISUAL_BEFORE"
python -X utf8 tests\winui\capture_search_panel.py --configuration Release --output C:\dev\flyExplorer\logs\search-v2-before.png
if ($LASTEXITCODE -ne 0) { throw "before capture failed" }

Write-Host "M19_NATIVE_RELEASE"
cmd /c tests\winui\m19\build.cmd Release
if ($LASTEXITCODE -ne 0) { throw "M19 Release build failed" }
cmd /c "set FLY_M19_CONFIG=Release&& python -X utf8 tests\winui\m19\test_native.py"
if ($LASTEXITCODE -ne 0) { throw "M19 native fixture failed" }

Write-Host "RELEASE_BUILD"
cmd /c build.bat Release
if ($LASTEXITCODE -ne 0) { throw "Release build failed" }

Write-Host "FOCUSED_SEARCH_V2_GUI"
python -X utf8 tests\winui\test_search_v2_gui.py
if ($LASTEXITCODE -ne 0) { throw "Search v2 GUI failed" }

Write-Host "VISUAL_AFTER"
python -X utf8 tests\winui\capture_search_panel.py --configuration Release --output C:\dev\flyExplorer\logs\search-v2-after.png
if ($LASTEXITCODE -ne 0) { throw "after capture failed" }

python -X utf8 -c "from PIL import Image,ImageChops; a=Image.open(r'C:\dev\flyExplorer\logs\search-v2-before.png').convert('RGB'); b=Image.open(r'C:\dev\flyExplorer\logs\search-v2-after.png').convert('RGB'); print('SEARCH_V2_VISUAL_SIZE',a.size,b.size); print('SEARCH_V2_VISUAL_DIFF_BBOX',ImageChops.difference(a,b).getbbox())"
if ($LASTEXITCODE -ne 0) { throw "visual diff inspection failed" }

git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "diff check failed" }
Write-Host "SEARCH_V2_PREMAIN_PASS"
